class TestValidationError:
    """Tests for custom ValidationError exception."""

    def test_basic_exception(self):
        """Basic exception with message only."""
        err = ValidationError("validation failed")
        assert err.message == "validation failed"
        assert err.errors == {}
        assert str(err) == "validation failed"

    def test_exception_with_errors_dict(self):
        """Exception with detailed error dictionary."""
        errors = {"field": "invalid value"}
        err = ValidationError("validation failed", errors=errors)
        assert err.errors == errors
        assert err.message == "validation failed"

    def test_exception_inheritance(self):
        """Should inherit from Exception."""
        assert issubclass(ValidationError, Exception)

    def test_exception_raise_and_catch(self):
        """Should be catchable as Exception."""
        with pytest.raises(ValidationError) as exc_info:
            raise ValidationError("custom failure", {"code": 400})
        assert exc_info.value.message == "custom failure"
        assert exc_info.value.errors == {"code": 400}

    def test_exception_without_errors(self):
        """Errors should default to empty dict."""
        err = ValidationError("no details")
        assert err.errors == {}


