class TestIntegration:
    """Cross-schema integration and defensive tests."""

    def test_command_with_data_payload(self, valid_command, valid_data):
        """AgentCommand should accept AgentData as payload."""
        valid_command["payload"] = valid_data
        cmd = AgentCommand(**valid_command)
        assert cmd.payload["content_type"] == "application/json"

    def test_json_serialization_all_schemas(self, valid_command, valid_data, valid_config):
        """All schemas should serialize to JSON without error."""
        for model in [AgentCommand(**valid_command), AgentData(**valid_data), ConfigurationSchema(**valid_config)]:
            json_str = model.model_dump_json()
            assert json.loads(json_str) is not None

    def test_unknown_fields_rejected(self, valid_command):
        """Unknown fields should be ignored (not raise)."""
        valid_command["unknown"] = "value"
        cmd = AgentCommand(**valid_command)
        assert "unknown" not in cmd.model_dump()

    def test_none_values_for_optional_fields(self, valid_command):
        """Optional fields should accept None explicitly."""
        valid_command["payload"] = None
        valid_command["priority"] = 0
        cmd = AgentCommand(**valid_command)
        assert cmd.payload is None

    def test_unicode_strings_in_payload(self, valid_command):
        """Unicode strings should be handled correctly."""
        valid_command["payload"] = {"message": "héllo wörld 你好"}
        cmd = AgentCommand(**valid_command)
        assert cmd.payload["message"] == "héllo wörld 你好"

    def test_large_payload(self, valid_command):
        """Large payloads should be accepted."""
        valid_command["payload"] = {"data": "x" * 100000}
        cmd = AgentCommand(**valid_command)
        assert len(cmd.payload["data"]) == 100000

    def test_datetime_timezone_awareness(self, valid_command):
        """Datetime should be timezone-aware (UTC)."""
        cmd = AgentCommand(**valid_command)
        assert cmd.timestamp.tzinfo == timezone.utc
        assert cmd.timestamp.tzname() == "UTC"

    def test_validation_error_raised_from_pydantic(self, valid_command):
        """Pydantic errors should be catchable and convertible."""
        valid_command["priority"] = -1
        with pytest.raises(PydanticValidationError):
            AgentCommand(**valid_command)

    def test_model_dump_contains_expected_keys(self, valid_command):
        """Model dump should contain all schema fields."""
        cmd = AgentCommand(**valid_command)
        dump = cmd.model_dump()
        assert set(dump.keys()) == {"action", "target", "payload", "timestamp", "priority"}

    def test_checksum_validation_with_sha256(self, valid_data):
        """Checksum should match SHA-256 hex digest format."""
        import hashlib
        content = b"test-content"
        checksum = hashlib.sha256(content).hexdigest()
        valid_data["checksum"] = checksum
        data = AgentData(**valid_data)
        assert data.checksum == checksum
        assert len(data.checksum) == 64


