class TestPerformance:
    """Performance-oriented validation tests."""

    def test_bulk_validation_speed(self, valid_command):
        """Should handle bulk validation efficiently."""
        import time
        start = time.perf_counter()
        for _ in range(1000):
            AgentCommand(**valid_command)
        elapsed = time.perf_counter() - start
        assert elapsed < 2.0  # 1000 validations under 2 seconds

    def test_concurrent_validation(self, valid_command):
        """Should handle concurrent validation without race conditions."""
        from concurrent.futures import ThreadPoolExecutor

        def validate():
            return AgentCommand(**valid_command)

        with ThreadPoolExecutor(max_workers=10) as executor:
            results = list(executor.map(lambda _: validate(), range(100)))
        assert len(results) == 100
        assert all(r.action == "deploy" for r in results)

    def test_deeply_nested_payload(self, valid_command):
        """Deeply nested payloads should be accepted."""
        nested = {"level1": {"level2": {"level3": {"level4": {"level5": "deep"}}}}}
        valid_command["payload"] = nested
        cmd = AgentCommand(**valid_command)
        assert cmd.payload["level1"]["level2"]["level3"]["level4"]["level5"] == "deep"